app.MapGet("/orders/{id:int}", async (int id, OrderStore store) =>
{
    try
    {
        var order = await store.FindAsync(id);
        return order is null ? Results.NotFound() : Results.Ok(order);
    }
    catch (Exception ex)
    {
        // its own error shape, and ex.Message can expose SQL or file paths
        return Results.Json(new { error = ex.Message }, statusCode: 500);
    }
}); // ...repeated in every endpoint, until one forgets
app.Run();

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddProblemDetails();
builder.Services.AddSingleton<OrderStore>();
var app = builder.Build();

app.UseExceptionHandler(); // first: catches what everything after it throws
app.UseStatusCodePages();  // empty 4xx/5xx responses get a ProblemDetails body

app.MapGet("/orders/{id:int}", async (int id, OrderStore store) =>
    await store.FindAsync(id) is { } order
        ? Results.Ok(order)
        : Results.NotFound());
app.Run();

