using Microsoft.AspNetCore.Diagnostics;
using Microsoft.EntityFrameworkCore;

public sealed class ConcurrencyExceptionHandler(
    IProblemDetailsService problemDetails,
    ILogger<ConcurrencyExceptionHandler> logger) : IExceptionHandler
{
    public async ValueTask<bool> TryHandleAsync(
        HttpContext context, Exception exception, CancellationToken ct)
    {
        if (exception is not DbUpdateConcurrencyException)
            return false; // not ours: the next handler, or the default 500

        logger.LogWarning(exception, "Conflict on {Path}", context.Request.Path);
        context.Response.StatusCode = StatusCodes.Status409Conflict;
        return await problemDetails.TryWriteAsync(new()
        {
            HttpContext = context,
            ProblemDetails = { Title = "The order was changed by someone else." }
        });
    }
}
